{
  "implementation": "import heapq

def solve(case):
    payload = case['payload']
    nodes_raw = payload['nodes']
    threshold = payload['utility_threshold']

    # Validate nodes structure
    if not isinstance(nodes_raw, list):
        raise ValueError('nodes must be a list')
    required_fields = {'id', 'parent', 'symbol', 'depth', 'removable', 'utility'}
    nodes = {}
    children = {}
    root_id = None
    for node in nodes_raw:
        if not isinstance(node, dict):
            raise ValueError('each node must be a dict')
        missing = required_fields - set(node.keys())
        if missing:
            raise ValueError(f'node missing fields: {missing}')
        nid = node['id']
        parent = node.get('parent')
        if parent is None:
            if root_id is not None:
                raise ValueError('multiple roots found')
            root_id = nid
        else:
            children.setdefault(parent, []).append(nid)
        nodes[nid] = node
    if root_id is None:
        raise ValueError('no root node found')
    # Validate parent references
    for nid, node in nodes.items():
        pid = node['parent']
        if pid is not None and pid not in nodes:
            raise ValueError(f'node {nid} has non-existent parent {pid}')
    # Validate depth consistency (optional but good)
    for nid, node in nodes.items():
        depth = node['depth']
        pid = node['parent']
        if pid is not None:
            expected_depth = nodes[pid]['depth'] + 1
            if depth != expected_depth:
                raise ValueError(f'node {nid} depth {depth} inconsistent with parent depth')

    # Initialize queue: all nodes sorted by depth descending, then id ascending
    initial_queue = sorted(nodes.values(), key=lambda n: (-n['depth'], n['id']))
    queue = []
    in_queue = set()
    for node in initial_queue:
        heapq.heappush(queue, (-node['depth'], node['id'], node['id']))
        in_queue.add(node['id'])

    removed = set()
    visit_order = []

    while queue:
        neg_depth, _, nid = heapq.heappop(queue)
        if nid not in in_queue:
            continue  # stale entry
        in_queue.discard(nid)
        visit_order.append(nid)
        if nid in removed:
            continue
        node = nodes[nid]
        # Determine if leaf: all original children are removed (or none)
        child_ids = children.get(nid, [])
        is_leaf = all(cid in removed for cid in child_ids)
        if node['removable'] and is_leaf and node['utility'] <= threshold:
            removed.add(nid)
            parent_id = node['parent']
            if parent_id is not None and parent_id not in removed:
                parent_node = nodes[parent_id]
                if parent_id not in in_queue:
                    heapq.heappush(queue, (-parent_node['depth'], parent_id, parent_id))
                    in_queue.add(parent_id)

    # Build retained_ids sorted by depth desc, id asc
    retained = [nid for nid in nodes if nid not in removed]
    retained.sort(key=lambda nid: (-nodes[nid]['depth'], nid))

    return {
        'retained_ids': retained,
        'visit_order': visit_order
    }"
}
